```yaml
name: Auto-approve Copilot workflows
on:
  pull_request:
    paths:
      - '.github/workflows/auto-approve-copilot-workflows.yml'
    types: [opened, synchronize]
jobs:
  auto-approve:
    runs-on: ubuntu-latest
    steps:
      - name: Auto-approve Copilot workflows
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;

            // Check if this is a Copilot-generated workflow
            if (context.payload.pull_request.title.includes('Copilot') || 
                context.payload.pull_request.body?.includes('Copilot') ||
                context.payload.pull_request.title.includes('auto-approve')) {

              // Add review
              await github.rest.pulls.createReview({
                owner,
                repo,
                pull_number: prNumber,
                event: 'APPROVE',
                body: 'Auto-approved Copilot workflow changes'
              });

              // Add comment
              await github.rest.issues.createComment({
                owner,
                repo,
                issue_number: prNumber,
                body: 'This PR was automatically approved by the Copilot workflow approval system.'
              });
            }
